import{j as e}from"./blog-pages-Cba4hDr6.js";import{P as n}from"./compare-pages-BzMkvKVB.js";const o=[{factor:"Connection method",atlantis:"REST + OSLC",competitor:"Maximo Integration Framework (MIF), MAS APIs"},{factor:"Supported Maximo versions",atlantis:"Maximo 7.6.x, Maximo 8.x, Maximo Application Suite (MAS)",competitor:"Same"},{factor:"Authentication",atlantis:"OAuth2, API key, LDAP/SSO via Maximo standard",competitor:"—"},{factor:"Equipment master sync",atlantis:"Bi-directional, Maximo master of record",competitor:"—"},{factor:"Inspection findings → Maximo",atlantis:"Service Request creation with structured long description and FFS/RBI summary",competitor:"—"},{factor:"Work order completion → Atlantis",atlantis:"On WO close, status + actual cost + completion date sync back",competitor:"—"},{factor:"Deployment time",atlantis:"3–4 weeks typical",competitor:"—"},{factor:"Maximo prerequisites",atlantis:"REST API enabled, Maximo Integration Framework configured, dedicated integration user",competitor:"—"},{factor:"MAS-specific support",atlantis:"Maximo Health, Predict, and Manage objects supported via MAS APIs",competitor:"—"}],i=[{question:"Does this work with Maximo Application Suite (MAS) on OpenShift?",answer:"Yes. MAS exposes the same logical objects (Asset, Location, Service Request, Work Order, Job Plan, PM Record) via the MAS APIs over OAuth2. The connector code paths handle MAS authentication out of the box. We have customers running this on MAS 8.x deployed on Red Hat OpenShift."},{question:"What about Maximo Health and Maximo Predict?",answer:"Maximo Health (asset health scoring, criticality, and risk analysis) and Maximo Predict (predictive maintenance via IBM Watson AIoT) are supported. Atlantis FFS/RBI risk-band changes flow into Maximo Health asset risk scoring; Maximo Predict anomaly events on rotating equipment near a fixed asset flow into the Atlantis asset record so integrity engineers see operating-severity context."},{question:"Can we use Maximo as the system of record for the asset hierarchy?",answer:"Yes — and this is the recommended pattern. Maximo&rsquo;s Asset and Location hierarchies are the system of record. Atlantis attaches its inspection-domain extensions (CMLs, weld registers, RT/UT/PAUT scan archive, FFS calculations, RBI band) in its own data model, keyed to the Maximo Asset ID. Maximo is not extended or modified — Atlantis lives alongside without touching the Maximo schema."},{question:"How do FFS and RBI results flow into Maximo?",answer:"FFS results and RBI risk-band changes flow into Maximo as Service Requests with a structured long description containing the calculation summary, the recommended action, and a deep link back to the full Atlantis record. Service Requests then route into the standard Maximo Work Order workflow. Risk-driven inspection interval changes flow into the Maximo Job Plan / PM Record to update the next due date."},{question:"What happens to existing Maximo inspection records?",answer:"We migrate them into Atlantis during onboarding. Maximo&rsquo;s generic inspection records (Asset Meter readings, Inspection History) are mapped to Atlantis CML readings, weld inspection records, and inspection events. The migration is one-way (Maximo → Atlantis) and is typically a 1–2 week activity. After migration, ongoing inspection capture happens natively in Atlantis with the structured CML / weld / FFS / RBI workflow, while Maximo continues to be the system of record for the asset hierarchy and the work order workflow."}];function c(){const a={"@context":"https://schema.org","@graph":[{"@type":"SoftwareApplication",name:"Atlantis Digital Twin — IBM Maximo Integration",applicationCategory:"BusinessApplication",operatingSystem:"Web",description:"Native IBM Maximo integration via REST + OSLC. Supports Maximo 7.6, 8.x, Maximo Application Suite. Bi-directional asset master sync, inspection findings → Service Requests → Work Orders. 3-4 wk deploy.",offers:{"@type":"Offer",availability:"https://schema.org/InStock"},provider:{"@type":"Organization",name:"Atlantis NDT"}},{"@type":"Article",headline:"Atlantis Digital Twin — IBM Maximo Integration [2026]",datePublished:"2026-05-09",dateModified:"2026-05-09",author:{"@type":"Person",name:"Anoop Rayavarapu"},publisher:{"@type":"Organization",name:"Atlantis NDT"}},{"@type":"FAQPage",mainEntity:i.map(t=>({"@type":"Question",name:t.question,acceptedAnswer:{"@type":"Answer",text:t.answer}}))}]};return e.jsx(n,{title:"Atlantis Digital Twin — IBM Maximo Integration: REST/OSLC, MAS, Health [2026]",description:"IBM Maximo + MAS integration for Atlantis Digital Twin: REST + OSLC, bi-directional asset master, inspection findings → Service Requests → Work Orders. 3-4 weeks to production.",canonical:"https://atlantisndt.com/integrations/ibm-maximo",eyebrow:"Integration",h1:"Atlantis Digital Twin — IBM Maximo Integration: REST + OSLC, MAS-Ready [2026]",intro:"Bi-directional REST + OSLC integration to IBM Maximo and Maximo Application Suite. Asset hierarchy flows Maximo → Atlantis; inspection findings, FFS/RBI changes, and recommended work flow Atlantis → Maximo as Service Requests. 3–4 weeks to production.",heroGradient:"from-sky-700 to-blue-800",competitorLabel:"Notes",compareRows:o,faqs:i,related:[{href:"/integrations/sap-pm",title:"SAP PM Integration",blurb:"Equivalent integration for SAP Plant Maintenance shops."},{href:"/integrations/ge-vernova-apm",title:"GE Vernova APM Integration",blurb:"Bi-directional APM sync — Meridium-derived."},{href:"/compare/atlantis-dt-vs-ibm-maximo",title:"vs IBM Maximo (Comparison)",blurb:"When to use Maximo, when to add Atlantis on top."},{href:"/digital-twins",title:"Atlantis Digital Twin",blurb:"Product page — features, pricing, case studies."},{href:"/erp",title:"Atlantis NDT ERP",blurb:"Companion ERP — jobs, certs, equipment, invoicing."},{href:"/contact",title:"Book a Scoping Call",blurb:"60-minute call with a Level III consultant + integration architect."}],ctaTitle:"Plug Atlantis Into Your Maximo",ctaSubtitle:"Bring your Maximo org and a sample asset export. We’ll show the integration in 30 minutes.",structuredData:a,bodyChildren:e.jsxs(e.Fragment,{children:[e.jsx("h2",{children:"Architecture overview"}),e.jsx("p",{children:"Atlantis Digital Twin integrates with IBM Maximo via REST and OSLC. Authentication is OAuth2 (recommended) or API key for legacy environments; LDAP/SSO via Maximo’s standard authentication framework is supported for federated identity. A dedicated Maximo integration user is created with read access to Asset, Location, and PM/Job Plan objects, and write access to Service Request. We do not require Maximo administrator privileges."}),e.jsx("h2",{children:"Data flow"}),e.jsx("p",{children:"Asset hierarchy and Location hierarchy flow Maximo → Atlantis on a scheduled sync (default: every 4 hours, configurable). Maximo is the system of record. Atlantis attaches its inspection-domain extensions — CMLs, weld registers, RT/UT/PAUT scan archive, FFS calculations, RBI band — to the asset record in its own data model. Maximo is not modified or extended."}),e.jsx("p",{children:"Inspection findings, FFS results, and RBI risk-band changes flow Atlantis → Maximo as Service Requests with a structured long description containing the calculation summary, the recommended action, and a deep link back to the full Atlantis record. Service Requests then route into the standard Maximo Work Order workflow per your site’s ticket triage rules."}),e.jsx("p",{children:"Work Order completion data — actual cost, completion date, technician, parts used — flows back Maximo → Atlantis on Work Order close. This closes the loop in Atlantis (the integrity engineer sees that the recommended work was done) and feeds the integrity-program KPI dashboards."}),e.jsx("h2",{children:"Deployment timeline"}),e.jsxs("ul",{children:[e.jsxs("li",{children:[e.jsx("strong",{children:"Week 1:"})," Maximo admin kickoff, integration user provisioning, sandbox connection test, asset schema review."]}),e.jsxs("li",{children:[e.jsx("strong",{children:"Week 2:"})," Initial asset hierarchy import, mapping validation, Service Request create test."]}),e.jsxs("li",{children:[e.jsx("strong",{children:"Week 3:"})," User acceptance testing with the integrity team, edge case validation, training."]}),e.jsxs("li",{children:[e.jsx("strong",{children:"Week 4:"})," Production cut-over, monitoring dashboards live, hypercare."]})]}),e.jsx("h2",{children:"MAS-specific notes"}),e.jsx("p",{children:"Maximo Application Suite on Red Hat OpenShift uses the MAS APIs over OAuth2. Functional integration is identical to traditional Maximo from Atlantis’ perspective; only the authentication setup differs slightly. We have customers running this in production on MAS 8.x. For MAS Health and MAS Predict, additional REST endpoints expose the asset health scoring and predictive event streams — Atlantis consumes these to enrich the asset record (rotating-equipment anomalies near fixed assets, risk score deltas) and to push integrity status changes back into MAS Health."}),e.jsx("h2",{children:"Migration of existing Maximo inspection records"}),e.jsx("p",{children:"Most Maximo customers have years of inspection records living in custom Maximo applications, Asset Meter readings, or attached PDF inspection reports. We migrate these into Atlantis as part of onboarding — typically 1–2 weeks of mapping work. After migration, ongoing inspection capture happens natively in Atlantis with the structured CML / weld / FFS / RBI workflow. Maximo continues to be the system of record for the asset hierarchy and the work order workflow. The two systems run in steady-state from week 4 onward."})]})})}export{c as default};
